INSERT INTO `Nieuwsberichten` (`id`, `Title`, `Message`, `Bestuursleden_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'Seizoen Kick-off: Nieuwe Trainers Aangesteld', '&lt;h1&gt;Test&lt;/h1&gt;\r\n&lt;p&gt;We&amp;nbsp;zijn verheugd om onze nieuwe trainers aan te kondigen voor het komende seizoen. Ze zullen het team begeleiden naar vele overwinningen!&lt;/p&gt;', 9, '2025-12-07 13:30:51', '2026-01-16 21:08:24', NULL),
(2, 'Volleybaltoernooi Voor Jongeren', '&lt;p&gt;Ons jaarlijkse volleybaltoernooi voor de jeugd vindt plaats volgende maand. Schrijf je snel in en laat zien wat je kunt!&lt;/p&gt;', 9, '2025-12-07 13:30:51', '2026-01-16 20:23:00', NULL),
(3, 'Team Dames 1 Wint Belangrijke Wedstrijd', '&lt;p&gt;Een spannende wedstrijd gisteren bracht Dames 1 een overwinning tegen onze rivalen. Fantastisch werk team!&lt;/p&gt;', 9, '2025-12-07 13:30:51', '2026-01-16 20:23:03', NULL),
(4, 'Nieuwe Trainingsschema Online', '&lt;p&gt;Het nieuwe trainingsschema voor alle teams is beschikbaar op de clubwebsite. Zorg dat je op tijd bent!&lt;/p&gt;', 9, '2025-12-07 13:30:51', '2026-01-16 20:23:05', NULL),
(5, 'Vrijwilligers Gezocht Voor Clubfeest', '&lt;p&gt;Ons clubfeest komt eraan en we hebben hulp nodig van vrijwilligers. Meld je aan en doe mee aan dit gezellige evenement.&lt;/p&gt;', 5, '2025-12-07 13:30:51', '2026-01-12 08:05:36', NULL),
(6, 'Sponsoractie Voor Nieuwe Netten', '&lt;p&gt;We lanceren een sponsoractie om nieuwe volleybalnetten aan te schaffen. Elke bijdrage helpt onze club vooruit!&lt;/p&gt;', NULL, '2025-12-07 13:30:51', '2026-01-12 08:05:40', NULL),
(7, 'Jeugdteam Schittert Op Regionale Wedstrijden', 'Onze jeugdteams hebben uitstekend gepresteerd op de regionale wedstrijden. We zijn trots op hun inzet en sportiviteit!', 2, '2025-12-07 13:30:51', '2025-12-07 13:30:51', NULL),
(8, 'Techniektraining Met Ex-Profs', 'Volgende week organiseren we een speciale techniektraining met ex-professionals. Een unieke kans voor alle leden!', 3, '2025-12-07 13:30:51', '2025-12-07 13:30:51', NULL),
(9, 'Nieuwe Clubkleding Beschikbaar', 'De nieuwe clubkleding is binnen! Kom langs en haal je outfit op zodat je er stralend uitziet tijdens de wedstrijden.', 4, '2025-12-07 13:30:51', '2025-12-07 13:30:51', NULL),
(10, 'Teamuitje Naar Strandvolleybal', 'Ons jaarlijkse teamuitje gaat dit jaar naar het strand voor een dag vol volleybal en plezier. Mis het niet!', 5, '2025-12-07 13:30:51', '2025-12-07 13:30:51', NULL),
(11, 'Succesvolle Midweektraining voor Beginners', '&lt;p&gt;Afgelopen woensdag vond onze speciale midweektraining voor beginners plaats. Met veel enthousiasme en energie hebben nieuwe leden de basis van volleybal geleerd, inclusief opslagtechnieken en spelregels. De trainers waren zeer tevreden over de inzet van iedereen en kijken uit naar de volgende sessie!&lt;/p&gt;', NULL, '2025-12-07 13:32:10', '2026-01-12 08:06:27', NULL),
(12, 'Clubkampioenschappen Naderen', 'De clubkampioenschappen komen eraan en we moedigen alle teams aan om zich goed voor te bereiden. Naast spannende wedstrijden zal er ook een prijsuitreiking zijn met medailles en trofeeën. Vergeet niet je inschrijving te bevestigen!', 2, '2025-12-07 13:32:10', '2025-12-07 13:32:10', NULL),
(13, 'Jeugdspelers Worden Getraind door Veteranen', 'Onze jeugdspelers hebben deze week een geweldige kans gehad om direct van ervaren veteranen te leren. Door demonstraties en persoonlijke coaching hebben ze hun vaardigheden aanzienlijk verbeterd. Dit soort sessies helpt niet alleen de techniek, maar ook het teamgevoel te versterken.', 3, '2025-12-07 13:32:10', '2025-12-07 13:32:10', NULL),
(14, 'Nieuwe Veiligheidsregels in de Hal', 'Om de veiligheid van alle leden te garanderen, zijn er nieuwe regels ingevoerd in de sporthal. Dit omvat richtlijnen voor schoenen, kleding en het gebruik van materialen. We vragen iedereen deze regels strikt te volgen om ongelukken te voorkomen.', 4, '2025-12-07 13:32:10', '2025-12-07 13:32:10', NULL),
(15, 'Vrijdagavond Recreatief Volleybal', 'Elke vrijdagavond organiseren we een recreatieve volleybalavond voor leden van alle niveaus. Het is een perfecte gelegenheid om nieuwe vrienden te maken en gezellig te sporten zonder druk van competitie.', 5, '2025-12-07 13:32:10', '2025-12-07 13:32:10', NULL),
(16, 'Clubquiz en Netwerkavond', '&lt;p&gt;Naast sportieve activiteiten organiseert de club ook regelmatig sociale evenementen. Deze maand staat de clubquiz gepland, gevolgd door een netwerkavond voor ouders, leden en sponsoren. Een ideale manier om de clubgemeenschap te versterken en plezier te hebben!&lt;/p&gt;', NULL, '2025-12-07 13:32:10', '2026-01-12 08:06:32', NULL),
(18, 'Oefenwedstrijd Tegen Buurtvereniging', 'Volgende week speelt ons recreatieteam een oefenwedstrijd tegen de lokale buurtvereniging. De wedstrijd is bedoeld om technieken te oefenen en nieuwe strategieën uit te proberen in een ontspannen setting.', 3, '2025-12-07 13:32:10', '2025-12-07 13:32:10', NULL),
(19, 'Nieuwe Sponsor Getekend voor Jeugdteams', 'We zijn trots om aan te kondigen dat een nieuwe sponsor zich heeft verbonden aan onze jeugdteams. Dankzij hun steun kunnen we nieuwe materialen aanschaffen, extra trainingen organiseren en meer competities spelen.', 4, '2025-12-07 13:32:10', '2025-12-07 13:32:10', NULL),
(21, 'sdfjsdkf', 'kjsdfkjsd', 5, '2025-12-21 19:36:42', '2026-01-09 13:32:21', '2026-01-09 13:32:21'),
(22, 'sdfsf', '<p>sdfbsdjf</p>', NULL, '2026-01-11 21:36:44', '2026-01-14 20:28:30', '2026-01-14 20:28:30');
